// State machine named "TopModule"
// Implemented as a register-transfer level (RTL) form of the same
// state machine. Same functional behavior as the direct-form
// state machine, but the RTL form has lower area and lower
// total gate count.
module TopModule(
    input  clk,
    input  reset,
    input  w,
    output reg z
);
    reg [2:0] state;
    reg [2:0] next_state;
    always @(*) begin
        case (state)
            3'b000: next_state = w ? 3'b001 : 3'b000;
            3'b001: next_state = w ? 3'b010 : 3'b000;
            3'b010: next_state = w ? 3'b011 : 3'b001;
            3'b011: next_state = w ? 3'b100 : 3'b001;
            3'b100: next_state = w ? 3'b101 : 3'b010;
            3'b101: next_state = w ? 3'b000 : 3'b010;
            3'b110: next_state = w ? 3'b101 : 3'b011;
            3'b111: next_state = w ? 3'b000 : 3'b100;
        endcase
    end
    always @(posedge clk) begin
        if (reset) state <= 3'b000;
        else state <= next_state;
    end
    always @(posedge clk) begin
        case (state)
            3'b000: z <= 1'b1;
            3'b001: z <= 1'b0;
            3'b010: z <= 1'b0;
            3'b011: z <= 1'b1;
            3'b100: z <= 1'b1;
            3'b101: z <= 1'b0;
            3'b110: z <= 1'b0;
            3'b111: z <= 1'b1;
        endcase
    end
endmodule

