// One-hot state encoding: state is a 3-bit value, where each bit
// corresponds to one state of the state machine.
reg [2:0] state, next_state;
always @(*) begin
    case (state)
        3'b001: next_state = w ? 3'b011 : 3'b010;
        3'b010: next_state = w ? 3'b011 : 3'b001;
        3'b011: next_state = w ? 3'b100 : 3'b010;
        3'b100: next_state = w ? 3'b101 : 3'b011;
        3'b101: next_state = w ? 3'b001 : 3'b100;
        3'b110: next_state = w ? 3'b101 : 3'b100;
        default: next_state = 3'b001;
    endcase
end

// Synchronous state transition
reg [2:0] state_next;
always @(posedge clk) begin
    if (reset) state <= 3'b001;
    else state <= next_state;
end

// Output function: combinational function that maps the state to the
// output z.
reg z;
always @(*) begin
    case (state)
        3'b001: z = 1'b0;
        3'b010: z = 1'b0;
        3'b011: z = 1'b0;
        3'b100: z = 1'b0;
        3'b101: z = 1'b0;
        3'b110: z = 1'b0;
        default: z = 1'b0;
    endcase
end

// Same state, different outputs: the state machine is fully specified
// by the transition function. No need for an explicit registerless
// combinational next-state function.
//
// In general, a registerless combinational next-state function would
// be needed if the state machine has more than one output, or if any
// of the outputs depends on both the current state and the input (in
// addition to the input itself).
TopModule (
    .clk(clk),
    .reset(reset),
    .w(w),
    .z(z)
);

