    always @(*) begin
        case (state)
            3'b000: next_state = w ? 3'b100 : 3'b001;
            3'b001: next_state = w ? 3'b001 : 3'b000;
            3'b010: next_state = w ? 3'b011 : 3'b011;
            3'b011: next_state = w ? 3'b010 : 3'b000;
            3'b100: next_state = w ? 3'b110 : 3'b001;
            3'b101: next_state = w ? 3'b001 : 3'b010;
            3'b110: next_state = w ? 3'b111 : 3'b001;
            3'b111: next_state = w ? 3'b001 : 3'b010;
